package main
import("fmt";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/mir2")
func main(){v:=func(n string)hir.Expr{return hir.Var(n,mir2.TyU16)};f:=&hir.Func{Name:"scopegoto",RetTy:mir2.TyU16,Params:[]hir.Param{{Name:"x",Ty:mir2.TyU16}},Body:hir.Blk(hir.Decl("i",mir2.TyU16,hir.U16(0)),&hir.LabelStmt{Name:"again"},hir.Blk(&hir.AssignStmt{Target:v("i"),Val:&hir.BinExpr{Op:"+",L:v("i"),R:hir.U16(1),Ty:mir2.TyU16}},hir.Decl("x",mir2.TyU16,hir.U16(99)),&hir.IfStmt{Cond:&hir.BinExpr{Op:"<",L:v("i"),R:hir.U16(2),Ty:mir2.TyBool},Then:hir.Blk(&hir.GotoStmt{Label:"again"})}),&hir.ReturnStmt{Val:v("x")})};m:=&hir.Module{Funcs:[]*hir.Func{f}};fmt.Println("Verify",hir.Verify(m));got,e:=mir2.NewVM(hir.LowerModule(m)).Call("scopegoto",[]mir2.Value{{I:7}});fmt.Println("gotoresult",got,"want7 error",e)}
